import hashlib,subprocess,sys
R=sys.argv[1]
def git(*a):
    return subprocess.run(['git','-C',R]+list(a),capture_output=True,text=True).stdout
def sha_at(c,p):
    data=subprocess.run(['git','-C',R,'show',c+':'+p],capture_output=True).stdout
    return hashlib.sha256(data).hexdigest()[:8]
for p in ['tools/mutate-and-run.sh','tools/bash-witness-study.py']:
    print('== history of', p)
    for c in git('log','--format=%H','--reverse','--',p).split():
        print(c[:8], sha_at(c,p), git('log','-1','--format=%ad %s','--date=short',c).strip()[:150])
print('HEAD', p, sha_at('HEAD','tools/bash-witness-study.py'), sha_at('HEAD','tools/mutate-and-run.sh'))
print('28aeef4 is ancestor of HEAD:', subprocess.run(['git','-C',R,'merge-base','--is-ancestor','28aeef4','HEAD']).returncode==0)
